function meaningfulPresentationText(value){const text=nonEmptyText(value);return text&&!text.replace(/[\s\-–—\\/|•·]+/g,'')?'':text;}
function reportBlock(m,result){if(!result?.report?.available)return "";const sourceItems=Array.isArray(result.report.sourceGroundedProjection)?result.report.sourceGroundedProjection:[];const sourceLabels={current_cv:m.sourceCurrentCv,previous_cv:m.sourcePreviousCv,professional_declaration:m.sourceDeclaration};const sourceBlock=sourceItems.length?`<section class="source-grounded-representation"><h2>${escapeHtml(m.sourceGroundedRepresentationTitle)}</h2><p>${escapeHtml(m.sourceGroundedRepresentationIntro)}</p>${sourceItems.map(x=>`<article><h3>${escapeHtml(sourceLabels[x.sourceRole]||x.sourceRole)}</h3><ul>${(x.facts||[]).map(f=>`<li>${escapeHtml(f)}</li>`).join("")}</ul></article>`).join("")}${result.report.targetRole?`<p><strong>${escapeHtml(m.understandingTarget)}:</strong> ${escapeHtml(result.report.targetRole)}. ${escapeHtml(m.targetContextBoundary)}</p>`:""}</section>`:"";const representation=result.report.professionalRepresentation;const canonicalClaims=Array.isArray(representation?.claims)?representation.claims:[];if(canonicalClaims.length){return `${sourceBlock}<section><h2>${escapeHtml(m.valueProofTitle)}</h2><p>${escapeHtml(m.valueProofIntro)}</p>${canonicalClaims.map(c=>`<article class="value-proof-claim"><h3>${escapeHtml(m.representationWhatEmerges)}</h3><p>${escapeHtml(c.professionalClaim)}</p><details><summary>${escapeHtml(m.valueProofWhy)}</summary><h4>${escapeHtml(m.representationWhyEmerges)}</h4><p>${escapeHtml(c.explanation)}</p><p><strong>${escapeHtml(m.representationEpistemicState)}:</strong> ${escapeHtml(c.epistemicState==='observed'?m.representationObserved:c.epistemicState)}</p>${c.representationDetails?.length?`<dl class="representation-details">${c.representationDetails.map(d=>`<dt>${escapeHtml(m["representationDetail_"+d.kind]||m[{observed_context:"representationObservedContext",person_contribution:"representationPersonContribution",responsibility_boundary:"representationResponsibilityBoundary",outcome:"representationOutcome",quantification:"representationQuantification"}[d.kind]]||"")}</dt><dd>${escapeHtml(d.value)}</dd>`).join("")}</dl>`:""}${c.supportingEvidence?.length?`<h4>${escapeHtml(m.representationEvidence)}</h4><ul>${c.supportingEvidence.map(e=>`<li>${escapeHtml(e.summary)}</li>`).join("")}</ul>`:""}${c.limitations?.length?`<h4>${escapeHtml(m.representationLimitations)}</h4><ul>${c.limitations.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}</details></article>`).join("")}</section>`;}const projection=result.report.representationValueProof;const claims=Array.isArray(projection?.claims)?projection.claims:[];if(claims.length){return `${sourceBlock}<section><h2>${escapeHtml(m.valueProofTitle)}</h2><p>${escapeHtml(m.valueProofIntro)}</p>${claims.map(c=>`<article class="value-proof-claim"><h3>${escapeHtml(c.claim)}</h3><details><summary>${escapeHtml(m.valueProofWhy)}</summary><p><strong>${escapeHtml(m.valueProofStatus)}:</strong> ${escapeHtml(m['valueProofStatus_'+c.epistemicStatus]||c.epistemicStatus)}</p><p>${escapeHtml(c.supportingEvidence?.length?m.valueProofWhyPattern:m.valueProofWhyLimited)}</p>${c.supportingEvidence?.length?`<h4>${escapeHtml(m.valueProofEvidence)}</h4><ul>${c.supportingEvidence.map(e=>`<li>${escapeHtml(e.summary)}</li>`).join("")}</ul>`:""}</details></article>`).join("")}</section>`;}const p=result.report.professionalPerceptionReport?.professionalPerception?.perceptionV2||{};const messages=[p?.whoEmerges?.narrative,p?.credibilityAssets?.narrative,p?.targetDistance?.bridgeNarrative].filter(Boolean).slice(0,3);return `${sourceBlock}<section><h2>${escapeHtml(m.report)}</h2>${messages.map(x=>`<p>${escapeHtml(x)}</p>`).join("")}</section>`;}



