 const d=feedback.semanticDetail,scope=d.peopleScope||{},context=d.professionalContext||{};
 const scopeText=scope.kind==="exact"?fillMessage(m.directionKnowledgeScopeExact,{count:scope.value}):scope.kind==="range"?fillMessage(m.directionKnowledgeScopeRange,{min:scope.min,max:scope.max}):scope.kind==="category"?fillMessage(m.directionKnowledgeScopeCategory,{scope:scope.value}):"";
