function candidateSourceDisplayLabels(sources,m){const base=x=>x?.title||x?.label||x?.role||x?.context||({current_cv:m.sourceCurrentCv,previous_cv:m.sourcePreviousCv,professional_declaration:m.sourceDeclaration})[x?.sourceRole]||m.sourceDeclaration;const counts=new Map();return (sources||[]).map(x=>{const b=base(x),k=`${x?.sourceRole||''}::${b}`;counts.set(k,(counts.get(k)||0)+1);return counts.get(k)>1?`${b} ${counts.get(k)}`:b;});}

function compactPreview(value,max=220){const t=String(value||'').replace(/\s+/g,' ').trim();return t.length<=max?t:`${t.slice(0,max-1).trim()}…`;}
function profileMaterialTypeLabel(m,source={}){
 const role=String(source?.sourceRole||'');
 if(role==='current_cv')return m.profileMaterialTypeCurrentCv;
 if(role==='previous_cv')return m.profileMaterialTypePreviousCv;
 if(role==='professional_declaration')return m.profileMaterialTypeDeclaration;
 return m.profileMaterialTypeOther;
}
function profileMaterialDisplayLabel(m,source={},asset=null,index=0){
 const filename=String(asset?.originalFilename||source?.metadata?.originalFilename||source?.metadata?.filename||'').trim();
 if(filename)return filename;
 const explicit=String(source?.label||source?.metadata?.title||'').trim();
 if(explicit&&!/^current cv$|^previous cv$|^professional declaration$/i.test(explicit))return explicit;
 const role=String(source?.sourceRole||'');
 if(role==='current_cv')return m.profileMaterialTypeCurrentCv;
 if(role==='previous_cv')return m.profileMaterialTypePreviousCv;
 if(role==='professional_declaration')return `${m.profileMaterialTypeDeclaration}${index>0?` ${index+1}`:''}`;
 return m.profileMaterialTypeOther;
}

