  direct_bounded_responsibility:m.profileEnumDirectBoundedResponsibility,broader_responsibility:m.profileEnumBroaderResponsibility,exclusive_final_authority:m.profileEnumExclusiveFinalAuthority,contextual_no_direct_responsibility:m.profileEnumContextualNoDirectResponsibility,insufficient:m.profileEnumBounded,
