 if(phase==='purpose_opportunity_application'||purpose==='opportunity_application')return {route:'/private-beta?purpose=opportunity_application',functionArea:'application',workflowStep:phase||'application'};
 if(phase==='purpose_build_enrich'||purpose==='professional_identity_build_enrich')return {route:'/private-beta?purpose=professional_identity_build_enrich',functionArea:'enrichment',workflowStep:phase||'enrichment'};
