function candidateNavigationActiveKey(phase,result){
 const purpose=result?.navigationTarget||result?.productPurpose||result?.preInterview?.productPurpose||'';
 if(phase==='backup')return 'backup';
 if(phase==='profile')return 'profile';
 if(phase==='purpose_understand'||purpose==='professional_representation_understand')return 'representation';
 if(phase==='purpose_direction_explore'||phase==='purpose_direction_acquisition'||purpose==='professional_direction_explore')return 'direction';
 if(phase==='purpose_opportunity_application'||purpose==='opportunity_application')return 'application';
 if(phase==='purpose_build_enrich'||purpose==='professional_identity_build_enrich')return 'enrich';
 if(['understanding','interview','feedback','complete'].includes(phase)||purpose==='interview_practice')return 'interview';
 return 'home';
}
